fetch(
      `/api/plant-module/shift-logs/by-date/${encodeURIComponent(form.date)}?plant=${encodeURIComponent(form.plantName)}`,
      { credentials: "include", signal: ctrl.signal }
    )
      .then(r => r.ok ? r.json() : null)
      .then((log: any) => {
