        const src: "TANK_1" | "TANK_2" =
          (log?.dryerFedFrom === "TANK_1" || log?.dryerFedFrom === "TANK_2")
            ? log.dryerFedFrom
            : "TANK_2";
        setForm(prev => {
          // Don't overwrite a manual operator pick.
          if (prev.dryerFedFrom !== null && prev.dryerFedFrom !== autoFilledDryerRef.current) return prev;
