                              <tr key={idx} className={`border-b hover:bg-muted/30 ${r.isLegacy ? 'bg-slate-50/60 dark:bg-slate-900/20' : isMismatch ? 'bg-amber-50/60 dark:bg-amber-950/20' : ''}`} data-testid={`recon-row-${idx}`}>
